INSERT INTO public.plants (name, botanical_name, origin_year, description, uses, benefits, precautions, rating, image_url, price, stock, category) VALUES
('Ashwagandha', 'Withania somnifera', '6000 BC', 'Ashwagandha is an ancient medicinal herb with multiple health benefits. It can reduce anxiety and stress, help fight depression, boost fertility and testosterone in men, and even boost brain function.', '["Stress relief", "Anxiety reduction", "Sleep aid"]', '["Lowers cortisol levels", "Boosts brain function", "Reduces inflammation"]', 'Avoid if pregnant or breastfeeding. May interact with thyroid medications.', 4.8, 'https://images.unsplash.com/photo-1611078488986-2621d7556b8d', 15.99, 100, 'Immunity'),
('Turmeric', 'Curcuma longa', '4000 BC', 'Turmeric is the spice that gives curry its yellow color. It has been used in India for thousands of years as a spice and medicinal herb. Curcumin is the main active ingredient in turmeric.', '["Cooking spice", "Anti-inflammatory supplements", "Skin care"]', '["Potent anti-inflammatory", "Strong antioxidant", "Brain function boost"]', 'High doses may cause digestive issues. Use caution with blood thinners.', 4.7, 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5', 12.50, 150, 'Immunity'),
('Tulsi (Holy Basil)', 'Ocimum tenuiflorum', '3000 BC', 'Tulsi is considered a tonic for the body, mind, and spirit. Different parts of the plant are recommended for treating different conditions.', '["Tea", "Extracts", "Essential oils"]', '["Reduces stress", "Boosts immunity", "Respiratory support"]', 'May slow blood clotting.', 4.9, 'https://images.unsplash.com/photo-1629196914168-3a9644338dc7?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8dHUlMjBzaSUyMHBsYW50fGVufDB8fDB8fHww', 9.99, 200, 'Ayurvedic Classics'),
('Aloe Vera', 'Aloe barbadensis miller', '16th Century BC', 'Aloe vera is a succulent plant species of the genus Aloe. It is widely used in the cosmetic and alternative medicine industries, being marketed as having various rejuvenating, healing, or soothing properties.', '["Topical gel", "Juice", "Skincare products"]', '["Heals burns", "Improves digestive health", "Clear skin"]', 'Oral use can cause stomach cramps.', 4.6, 'https://images.unsplash.com/photo-1596547609652-9cf5d8d76921', 14.00, 80, 'Skin'),
('Ginger', 'Zingiber officinale', '500 BC', 'Ginger is a flowering plant whose rhizome, ginger root or ginger, is widely used as a spice and a folk medicine.', '["Tea", "Spice", "Supplements"]', '["Nausea relief", "Pain reduction", "Anti-inflammatory"]', 'May increase bleeding risk.', 4.8, 'https://images.unsplash.com/photo-1615485925694-a6c336304299', 8.50, 120, 'Digestion'),
('Neem', 'Azadirachta indica', '2000 BC', 'Neem trees are known for their pesticidal and insecticidal properties, but humans also use them for dental and skin health.', '["Oil", "Leaf extract", "Toothpaste"]', '["Treats acne", "Promotes gum health", "Blood purifier"]', 'Long term oral use may harm kidneys or liver.', 4.5, 'https://images.unsplash.com/photo-1714273207458-6190199341e6?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8bmVlbSUyMHBsYW50fGVufDB8fDB8fHww', 11.20, 90, 'Skin'),
('Amla (Indian Gooseberry)', 'Phyllanthus emblica', '1000 BC', 'Amla is a tree native to India. It produces fruit that are round, light greenish-yellow, and quite sour.', '["Powder", "Juice", "Raw fruit"]', '["High Vitamin C", "Hair growth", "Liver health"]', 'Can increase bleeding risk.', 4.9, 'https://images.unsplash.com/photo-1623227866882-c005c2077546?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8M3x8YW1sYXxlbnwwfHwwfHx8MA%3D%3D', 13.50, 110, 'Hair'),
('Brahmi', 'Bacopa monnieri', '6th Century AD', 'Brahmi is a staple plant in traditional Ayurvedic medicine. It grows in wet, tropical environments and is popular for its ability to improve memory.', '["Capsules", "Tea", "Oil"]', '["Memory boost", "Reduces ADHD symptoms", "Anxiety relief"]', 'May cause digestive issues.', 4.6, 'https://images.unsplash.com/photo-1620217672148-b94cb11a86b5?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8YnJhaG1pJTIwcGxhbnR8ZW58MHx8MHx8fDA%3D', 18.00, 60, 'Ayurvedic Classics'),
('Shatavari', 'Asparagus racemosus', '1500 BC', 'Shatavari is a species of asparagus common throughout India and the Himalayas. It is considered a general health tonic to improve vitality.', '["Powder", "Tablets", "Liquid extract"]', '["Hormonal balance", "Reproductive health", "Antioxidant"]', 'Allergic reactions in some people.', 4.7, 'https://images.unsplash.com/photo-1605188057233-e3335775088f?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8YXNwYXJhZ3VzJTIwcmFjZW1vc3VzfGVufDB8fDB8fHww', 16.50, 75, 'Ayurvedic Classics'),
('Guduchi (Giloy)', 'Tinospora cordifolia', '1000 BC', 'Guduchi is an herbaceous vine of the family Menispermaceae indigenous to the tropical areas of Bangladesh, India, Myanmar, and Sri Lanka.', '["Juice", "Capsules", "Powder"]', '["Immunity booster", "Chronic fever", "Respiratory health"]', 'Monitor blood sugar levels.', 4.8, 'https://images.unsplash.com/photo-1599556654540-d3895f680082?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8Z2lsb3l8ZW58MHx8MHx8fDA%3D', 10.99, 130, 'Immunity'),
('Arjuna', 'Terminalia arjuna', '7th Century AD', 'Arjuna is a tree in the genus Terminalia. It is commonly found in India where its bark is used in Ayurvedic medicine.', '["Bark powder", "Capsules", "Tea"]', '["Heart health", "Blood pressure control", "Antioxidant"]', 'May lower blood sugar.', 4.7, 'https://images.unsplash.com/photo-1674319874723-de742a2b2873?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8MTF8fHRlcm1pbmFsaWElMjBhcmp1bmF8ZW58MHx8MHx8fDA%3D', 14.99, 85, 'Heart'),
('Licorice (Mulethi)', 'Glycyrrhiza glabra', '2500 BC', 'Licorice root is one of the world’s oldest herbal remedies. It comes from the root of the licorice plant.', '["Tea", "Lozenges", "Liquid extract"]', '["Sore throat", "Digestive issues", "Skin conditions"]', 'Excessive use can raise blood pressure.', 4.6, 'https://images.unsplash.com/photo-1620217672220-b95a2f755463?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8bGljb3JpY2UlMjByb290fGVufDB8fDB8fHww', 9.50, 140, 'Digestion'),
('Triphala', 'Polyherbal formulation', '1500 BC', 'Triphala is an herbal preparation used in Ayurvedic medicine. It is a combination of three dried fruits: Amla, Bibhitaki, and Haritaki.', '["Powder", "Tablets", "Juice"]', '["Digestive health", "Detoxification", "Eye health"]', 'Can cause diarrhea in high doses.', 4.8, 'https://images.unsplash.com/photo-1620217672692-1a610c28d0c0?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8M3x8dHJpcGhhbGF8ZW58MHx8MHx8fDA%3D', 12.99, 115, 'Digestion'),
('Moringa', 'Moringa oleifera', '2000 BC', 'Moringa oleifera is a plant that is often called the drumstick tree, the miracle tree, the ben oil tree, or the horseradish tree.', '["Powder", "Capsules", "Tea"]', '["Nutrient rich", "Lowers blood sugar", "Anti-inflammatory"]', 'Root bark can be toxic.', 4.8, 'https://images.unsplash.com/photo-1556217257-44c800472617?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8bW9yaW5nYSUyMG9sZWlmZXJhfGVufDB8fDB8fHww', 11.99, 100, 'Immunity'),
('Cinnamon', 'Cinnamomum verum', '2800 BC', 'Cinnamon is a spice obtained from the inner bark of several tree species from the genus Cinnamomum.', '["Spice", "Tea", "Essential oil"]', '["Lowers blood sugar", "Heart health", "Anti-viral"]', 'Cassia cinnamon contains coumarin.', 4.7, 'https://images.unsplash.com/photo-1599817759841-48d9162336b9?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8Y2lubmFtb258ZW58MHx8MHx8fDA%3D', 8.99, 160, 'Diabetes'),
('Fenugreek', 'Trigonella foenum-graecum', '4000 BC', 'Fenugreek is an herb similar to clover that is native to the Mediterranean region, southern Europe, and western Asia.', '["Seeds", "Powder", "Leaves"]', '["Controls diabetes", "Boosts testosterone", "Milk production"]', 'May cause digestive upset.', 4.6, 'https://images.unsplash.com/photo-1615485290382-441e4d049cb5?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8ZmVudWdyZWVrfGVufDB8fDB8fHww', 7.99, 130, 'Diabetes'),
('Hibiscus', 'Hibiscus sabdariffa', '4000 BC', 'Hibiscus tea is an herbal tea made as an infusion from crimson or deep magenta-colored calyces (sepals) of the roselle (Hibiscus sabdariffa) flower.', '["Tea", "Extract", "Powder"]', '["Lowers blood pressure", "Liver health", "Weight loss"]', 'High doses may cause liver damage.', 4.7, 'https://images.unsplash.com/photo-1563614595-908c58664c7f?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8aGliaXNjdXMlMjB0ZWF8ZW58MHx8MHx8fDA%3D', 10.50, 100, 'Heart'),
('Peppermint', 'Mentha x piperita', '1000 BC', 'Peppermint is a hybrid mint, a cross between watermint and spearmint. Indigenous to Europe and the Middle East.', '["Tea", "Oil", "Capsules"]', '["Digestive relief", "Headache relief", "Fresh breath"]', 'Can cause heartburn.', 4.8, 'https://images.unsplash.com/photo-1628556270448-e7c537b1867c?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8M3x8cGVwcGVybWludHxlbnwwfHwwfHx8MA%3D%3D', 8.50, 140, 'Digestion'),
('Lavender', 'Lavandula', '2500 years ago', 'Lavender is a genus of 47 known species of flowering plants in the mint family, Lamiaceae.', '["Essential oil", "Tea", "Dried flowers"]', '["Sleep aid", "Stress reduction", "Skin health"]', 'May cause skin irritation.', 4.9, 'https://images.unsplash.com/photo-1598887142486-0b8f327151b2?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8bGF2ZW5kZXJ8ZW58MHx8MHx8fDA%3D', 13.99, 90, 'Skin'),
('Chamomile', 'Matricaria chamomilla', '1550 BC', 'Chamomile is the common name for several daisy-like plants of the family Asteraceae.', '["Tea", "Essential oil", "Capsules"]', '["Sleep aid", "Digestive health", "Blood sugar control"]', 'Allergic reactions possible.', 4.8, 'https://images.unsplash.com/photo-1527661591475-527312dd65f5?w=800&auto=format&fit=crop&q=60&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8Y2hhbW9taWxlfGVufDB8fDB8fHww', 9.99, 120, 'Immunity');
